// 与后端 ASSET_MAX_UPLOAD_BYTES 对齐（20 MiB）：超过此大小在 SDK 早拒，
// 避免把超大 base64 灌过 bridge/REST 后被后端或 Cloud Run（32 MiB body 限制）
// 以不透明错误截断。游戏应在上传前压缩（如 canvas.toBlob("image/webp", q)）。
const MAX_UPLOAD_BYTES = 20 * 1024 * 1024
class AssetsClient {
constructor(transport) {
this.transport = transport
}
get(input = {}) {
if (!input.assetId) {
throw new PolyverseRuntimeError("invalid_request", "assetId is required")
}
return this.transport.call("assets.get", input)
}
save(input = {}) {
if (!input.url && !input.assetId) {
throw new PolyverseRuntimeError("invalid_request", "url or assetId is required")
}
return this.transport.call("assets.save", input)
}
// 上传运行时本地生成的图像字节（base64）→ 宿主落公开 GCS → 返回永久 public_url。
// 与 save()（登记一个已有的 http(s) URL）互补：upload 收字节、save 收 URL。
// 典型用法：canvas.toDataURL/toBlob → base64 → upload → composeComment({content:public_url,kind:"image"})。
upload(data, options = {}) {
if (!data || typeof data !== "string") {
throw new PolyverseRuntimeError("invalid_request", "data is required and must be a base64 string")
}
// 估算解码后字节数（去掉可选 data: URI 前缀，只算 base64 主体），早拒超大图。
const base64 = data.startsWith("data:") ? (data.split(",", 2)[1] || "") : data
const approxBytes = Math.floor((base64.length * 3) / 4)
if (approxBytes > MAX_UPLOAD_BYTES) {
throw new PolyverseRuntimeError(
"invalid_request",
`image exceeds max upload size (${MAX_UPLOAD_BYTES} bytes); compress before upload`
)
}
return this.transport.call("assets.upload", { data, ...options })
}
}
