/**
* High-level LLM helper for playables. Wraps the generic multimodal channel so
* games call text / vision LLMs without hand-assembling the job shape or reading
* provider-internal payloads.
*
*   const { text, json } = await pv.llm.chat({ prompt: "..." })
*   const { text }       = await pv.llm.chat({ prompt: "...", images: [url] })
*
* Contract: capability is auto-selected (images → llm.chat.vision, else
* llm.chat); the answer is read ONLY from the job's top-level result_data
* ({type:"llm_text", text, json}). We never drill into provider_payload — that
* is exactly the leak this helper exists to eliminate.
*/
class LlmClient {
constructor(transport) {
this.transport = transport
// Reuse the generic multimodal client for the job LIFECYCLE (polling +
// terminal/failed-job handling) via waitForResult, so that logic lives in
// exactly one place. Submission stays here because this helper owns the LLM
// request shape and result parsing.
this.multimodal = new MultimodalClient(transport)
}
/**
* Run a text or vision LLM chat completion and return the normalized result.
*
* @param {object} input
* @param {string}   input.prompt         User prompt (required, non-empty).
* @param {string[]} [input.images]       Image URLs; non-empty → vision.
* @param {string}   [input.system]       System prompt.
* @param {string}   [input.model]        Model id; omit for platform default.
* @param {number}   [input.maxTokens]    Max output tokens.
* @param {number}   [input.temperature]  Sampling temperature.
* @param {"text"|"json"} [input.responseFormat] Preferred response format.
* @param {object}   [input.metadata]     Passed through to the job.
* @param {number}   [input.timeoutMs]    Poll timeout.
* @param {number}   [input.pollIntervalMs] Poll interval.
* @returns {Promise<{text: string, json: object|null, job: object}>}
*/
async chat(input = {}) {
const prompt = input.prompt
if (typeof prompt !== "string" || prompt.trim() === "") {
throw new PolyverseRuntimeError("invalid_request", "prompt is required and must be a non-empty string")
}
const hasImages = Array.isArray(input.images) && input.images.length > 0
const capability = hasImages ? "llm.chat.vision" : "llm.chat"
const parameters = { prompt }
if (typeof input.system === "string" && input.system.length > 0) {
parameters.system_prompt = input.system
}
if (input.maxTokens != null) {
parameters.max_tokens = input.maxTokens
}
if (input.temperature != null) {
parameters.temperature = input.temperature
}
if (input.responseFormat != null) {
parameters.response_format = input.responseFormat
}
if (hasImages) {
parameters.images = input.images
}
const generateBody = {
capability,
parameters,
wait: true
}
// Omit modelId entirely when the game does not pick one; the backend applies
// the platform default (and falls back to it for unknown ids anyway).
if (input.model != null) {
generateBody.modelId = input.model
}
if (input.metadata != null) {
generateBody.metadata = input.metadata
}
// Submit directly, then reuse the shared waitForResult for polling +
// failed-job handling. A failed job throws PolyverseRuntimeError("job_failed").
const submitted = await this.transport.call("multimodal.generate", generateBody)
const job = await this.multimodal.waitForResult({
jobId: submitted.id,
timeoutMs: input.timeoutMs,
pollIntervalMs: input.pollIntervalMs
})
// Read ONLY the top-level result_data. Accept either the snake_case wire
// form (result_data) or a camelized form (resultData) so the helper is
// robust to response-shape conversion in the transport layer.
const resultData = job?.resultData ?? job?.result_data
if (!resultData || typeof resultData.text !== "string") {
throw new PolyverseRuntimeError(
"runtime_invalid_response",
"LLM job succeeded but returned no result_data.text",
{ jobId: job?.id, status: job?.status }
)
}
return {
text: resultData.text,
json: resultData.json ?? null,
job
}
}
}
